        List<String> tok = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tok.add(st.nextToken());
        }
        TreeNode root = new TreeNode(Integer.parseInt(tok.get(0)));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tok.size()) {
            TreeNode cur = q.poll();
            if (i < tok.size() && !tok.get(i).equals("null")) {
                cur.left = new TreeNode(Integer.parseInt(tok.get(i)));
                q.add(cur.left);
            }
            i++;
            if (i < tok.size() && !tok.get(i).equals("null")) {
