from collections import deque


def gen(rng):
    def build(n, kind, vr):
        vals = [rng.randint(-vr, vr) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        if kind == 'random':
            free = [(0, 0), (0, 1)]
            for v in range(1, n):
                k = rng.randrange(len(free))
                free[k], free[-1] = free[-1], free[k]
                p, s = free.pop()
                if s == 0:
                    L[p] = v
                else:
                    R[p] = v
                free.append((v, 0))
                free.append((v, 1))
        elif kind == 'complete':
            for v in range(1, n):
                p = (v - 1) // 2
                if (v - 1) % 2 == 0:
                    L[p] = v
                else:
                    R[p] = v
        elif kind == 'chain':
            for v in range(1, n):
                if rng.random() < 0.5:
                    L[v - 1] = v
                else:
                    R[v - 1] = v
        elif kind == 'zigzag':
            for v in range(1, n):
                if v % 2 == 1:
                    L[v - 1] = v
                else:
                    R[v - 1] = v
        elif kind == 'leftchain':
            for v in range(1, n):
                L[v - 1] = v
        elif kind == 'broom':
            spine = min(2500, n // 2)
            for v in range(1, spine):
                if rng.random() < 0.5:
                    L[v - 1] = v
                else:
                    R[v - 1] = v
            free = [(spine - 1, 0), (spine - 1, 1)]
            for v in range(spine, n):
                k = rng.randrange(len(free))
                free[k], free[-1] = free[-1], free[k]
                p, s = free.pop()
                if s == 0:
                    L[p] = v
                else:
                    R[p] = v
                free.append((v, 0))
                free.append((v, 1))
        out = []
        q = deque([0])
        while q:
            u = q.popleft()
            if u == -1:
                out.append('null')
                continue
            out.append(str(vals[u]))
            q.append(L[u])
            q.append(R[u])
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    tests = ['5', '-7 3', '1 null 2', '1 2 null 3', '1 2 3 4 5 6 7', '1 2 null null 4 null 5',
             '1 2 3 null 4 5 null', '1 2 3 null 4 5 null 6 null null 7 8']
    for n in (2, 3, 4, 5, 6, 8, 10, 12):
        for kind in ('random', 'random', 'chain', 'zigzag'):
            tests.append(build(n, kind, rng.choice((2, 5, 100))))
    tests.append(build(9, 'complete', 3))
    tests.append(build(12, 'leftchain', 9))
    tests.append(build(200, 'random', 10 ** 9))
    tests.append(build(100000, 'random', 10 ** 9))
    tests.append(build(100000, 'complete', 10 ** 9))
    tests.append(build(5000, 'zigzag', 10 ** 9))
    tests.append(build(5000, 'chain', 3))
    tests.append(build(100000, 'broom', 10 ** 9))
    return tests
